-- V34__seed_deck_quizzes.sql
-- Thêm bộ ngân hàng Quiz (Luyện nhanh, Kiểm tra, Thử thách & Final Quiz) cho 50 Deck TOEIC

SET @admin_id = (SELECT id FROM users WHERE username = 'admin' LIMIT 1);
SET @toeic_exam_id = (SELECT id FROM exam_types WHERE code = 'TOEIC' LIMIT 1);


-- Quiz: ⚡ Luyện nhanh - Contracts (QUIZ-QUICK-L01)
    quiz_code, title, description, quiz_type, quiz_category, 
    deck_id, exam_type_id, level_id, time_limit_seconds, pass_score, 
    max_attempts, shuffle_questions, shuffle_options, total_questions, is_active, created_by
) VALUES (
    'QUIZ-QUICK-L01', '⚡ Luyện nhanh - Contracts', 'Bài luyện tập nhanh 5 câu cho chủ đề Contracts (Dưới 500).', 
    'MULTIPLE_CHOICE', 'NORMAL', 
    (SELECT id FROM decks WHERE deck_code = 'DECK-TOEIC-U500-L01' LIMIT 1), @toeic_exam_id, (SELECT id FROM proficiency_levels WHERE code = 'TOEIC_U500' LIMIT 1), 300, 60.0, 
    10, true, true, 5, true, @admin_id
) ON DUPLICATE KEY UPDATE title = VALUES(title), total_questions = VALUES(total_questions);

SET @quiz_id = (SELECT id FROM quizzes WHERE quiz_code = 'QUIZ-QUICK-L01' LIMIT 1);

VALUES (@quiz_id, 'Từ vựng ''Establish (v.)'' có nghĩa là gì?', 'MULTIPLE_CHOICE', 'Từ ''Establish (v.)'' có nghĩa là ''Thành lập, thiết lập''. Định nghĩa: to institute permanently, to bring about.', 10, 1, true, 0);
SET @q_id = LAST_INSERT_ID();

VALUES (@quiz_id, 'Từ vựng ''Obligation (n.)'' có nghĩa là gì?', 'MULTIPLE_CHOICE', 'Từ ''Obligation (n.)'' có nghĩa là ''Nghĩa vụ, bổn phận''. Định nghĩa: obligatory adj..', 10, 2, true, 0);
SET @q_id = LAST_INSERT_ID();

VALUES (@quiz_id, 'Nghĩa ''Giải quyết vấn đề, xác định'' tương ứng với từ tiếng Anh nào dưới đây?', 'MULTIPLE_CHOICE', 'Nghĩa ''Giải quyết vấn đề, xác định'' tương ứng với từ ''Determine (v.)''.', 10, 3, true, 0);
